#!/usr/bin/env node
import fs from "node:fs"; import path from "node:path"; import { fileURLToPath } from "node:url"; const __dirname = path.dirname(fileURLToPath(import.meta.url)), ROOT = path.resolve(__dirname, ".."), DOCS = path.join(ROOT, "docs"), SITE = "https://simply.js.org"; function parseSidebar() { const lines = fs.readFileSync(path.join(DOCS, "sidebar.md"), "utf8").split("\n"), items = []; let section = null; for (const line of lines) { const sectionMatch = line.match(/^- (?:<br>)?(.+)$/), itemMatch = line.match(/^\s*-\s*\[(.+?)\]\((.+?)\)\s*$/); itemMatch ? items.push({ section: section, label: itemMatch[1], href: itemMatch[2] }) : sectionMatch && (section = sectionMatch[1].trim()) } return items } function resolveHref(href) { if ("docs/" === href) return { file: path.join(ROOT, "README.md"), slug: "about", relPath: "docs/" }; const rel = href.replace(/^docs\//, ""), withExt = rel.endsWith(".md") ? rel : `${rel}.md`; return { file: path.join(DOCS, withExt), slug: withExt.replace(/\.md$/, "").replace(/\//g, "-"), relPath: `docs/${withExt}` } } function cleanContent(text, { slugByRelPath: slugByRelPath }) { let out = text; return out = out.replace(/^\?>\s?(.*)$/gm, "> **Note:** $1"), out = out.replace(/^!>\s?(.*)$/gm, "> **Warning:** $1"), out = out.replace(/<details>\s*<summary>\s*<ins>?Live demo<\/ins>?\s*<\/summary>\s*<repl-component[^>]*\/?>\s*(<\/repl-component>)?\s*<\/details>/gi, "> _Interactive live demo on the docs site (not reproduced in this text export)._"), out = out.replace(/<repl-component[^>]*>(\s*<\/repl-component>)?/gi, "> _Interactive live demo on the docs site (not reproduced in this text export)._"), out = out.replace(/<s-component-api[^>]*>(\s*<\/s-component-api>)?/gi, "> _Interactive component demo on the docs site (not reproduced in this text export)._"), out = out.replace(/\]\(\/#\/playground\)/g, `](${SITE}/#/playground)`), out = out.replace(/\]\((docs\/[^)#]+)(#[^)]*)?\)/g, ((m, target, anchor) => { const norm = target.endsWith(".md") ? target : `${target}.md`, key = `docs/${norm.replace(/^docs\//, "")}`; return slugByRelPath.has(key) ? `](#${slugByRelPath.get(key)})` : `](${SITE}/${norm.replace(/^docs\//, "docs/")})` })), out.trim() } function buildLlmsFull(items) { const resolved = items.map((it => ({ ...it, ...resolveHref(it.href) }))), slugByRelPath = new Map(resolved.map((r => [r.relPath, r.slug]))), missing = resolved.filter((r => !fs.existsSync(r.file))); missing.length && (console.warn("WARNING: missing files referenced in sidebar.md:"), missing.forEach((m => console.warn("  -", m.relPath)))); const toc = resolved.filter((r => fs.existsSync(r.file))).map((r => `- [${r.label}](#${r.slug})${r.section ? `  \x3c!-- ${r.section} --\x3e` : ""}`)).join("\n"), sections = resolved.filter((r => fs.existsSync(r.file))).map((r => { const demoted = cleanContent(fs.readFileSync(r.file, "utf8"), { slugByRelPath: slugByRelPath }).replace(/^#\s+/m, "## "); return `<a id="${r.slug}"></a>\n\n${demoted}` })); return `# simply.js — Full Documentation (LLM-ready, single file)\n\n> Generated from https://github.com/fehmi/simply.js/tree/main/docs — do not edit by hand, edit the source .md files and re-run \`node scripts/build-llms.mjs\`.\n> Canonical human docs: ${SITE} — Source: ${SITE}/llms.txt\n\n## Contents\n\n${toc}\n\n---\n` + "\n" + sections.join("\n\n---\n\n") + "\n" } function buildLlmsTxt(items) { const bySection = new Map; for (const it of items) { const key = it.section || "Docs"; bySection.has(key) || bySection.set(key, []), bySection.get(key).push(it) } const descriptions = { "docs/": "What simply.js is, design goals, and how it works.", "docs/getting-started.md": "Add the script tag, create your first component, serve it locally.", "docs/component-structure.md": "The `<html>`/`<style>`/`<script>` single-file component format.", "docs/template.md": "The template tag and what the template engine supports.", "docs/style.md": "The `<style>` tag: scoping, variables, conditions.", "docs/script.md": "The `<script>` tag: the `class simply { ... }` shape.", "docs/variables.md": "Reactive `{{ }}` variables: data, props, state, methods, etc.", "docs/conditionals.md": "Conditional rendering in templates.", "docs/loops.md": "`each` loops over arrays/objects in templates.", "docs/dom-events.md": "Binding DOM events (`onclick`, etc.) in templates.", "docs/nested-components.md": "Composing components inside components.", "docs/slot.md": "Slot-based content projection.", "docs/loadcomponent.md": "Loading/registering components with `get()`.", "docs/component-communication.md": "Parent/child communication patterns.", "docs/props.md": "Passing props into components.", "docs/lifecycle.md": "Component lifecycle hooks.", "docs/reactivity.md": "How the reactive data layer works.", "docs/state.md": "Cross-component state management.", "docs/style-variables.md": "CSS variables driven by component state.", "docs/style-conditions.md": "Conditional CSS classes/styles.", "docs/style-scope.md": "Style scoping and Shadow DOM encapsulation.", "docs/router.md": "The `go` client-side router.", "docs/framer.md": "Using simply.js inside Framer.", "docs/electron.md": "Using simply.js inside Electron apps.", "docs/chrome.md": "Using simply.js to build Chrome extensions.", "docs/agents/agents.md": "Overview of how AI agents/LLMs can consume these docs and (planned) APIs.", "docs/agents/ai-docs.md": "Where to fetch machine-readable docs (this file's own index).", "docs/agents/repl-api.md": "Planned REPL API for programmatic example access (TBD, not live yet)." }; let out = `# simply.js\n\n> Zero-dependency web-component library for building interactive UIs with plain HTML, CSS and JavaScript. Single-file components (\`<html>\`/\`<style>\`/\`<script>\` in one \`.html\` file), a reactive template engine, router and state management. No compiler, bundler, or build step — everything runs directly in the browser.\n\nUse this file to decide which page(s) to fetch. Every link is a plain Markdown file you can \`curl\`/fetch directly — this is a static site, no JavaScript execution required to read the docs. For one-shot ingestion of the whole library, fetch [llms-full.txt](${SITE}/llms-full.txt) instead of crawling page by page.\n\n`; for (const [section, list] of bySection) { out += `## ${section}\n`; for (const it of list) { const url = "docs/" === it.href ? `${SITE}/docs/` : `${SITE}/${it.href.replace(/^docs\//, "docs/")}`, desc = descriptions[it.href] ? `: ${descriptions[it.href]}` : ""; out += `- [${it.label}](${url})${desc}\n` } out += "\n" } return out += `## Optional\n\n- [Full documentation, single file](${SITE}/llms-full.txt): the entire library documentation concatenated into one Markdown file.\n- [Examples gallery](${SITE}/docs/examples.md): links to the runnable examples in the \`examples/\` folder of the repo.\n- [Playground](${SITE}/docs/playground.md): in-browser REPL to try simply.js without setting up a project.\n- [Source repository](https://github.com/fehmi/simply.js): source code, issues, and the \`examples/\` folder referenced above.\n`, out } function main() { const items = parseSidebar(), llmsFull = buildLlmsFull(items), llmsTxt = buildLlmsTxt(items); fs.writeFileSync(path.join(ROOT, "llms-full.txt"), llmsFull, "utf8"), fs.writeFileSync(path.join(ROOT, "llms.txt"), llmsTxt, "utf8"), console.log(`Wrote llms.txt (${llmsTxt.length} bytes) and llms-full.txt (${llmsFull.length} bytes) to ${ROOT}`) } main();